--
-- Table structure for table `penilaian_akademik`
--

CREATE TABLE `penilaian_akademik` (
  `id` int(10) UNSIGNED NOT NULL,
  `siswa_id` int(10) UNSIGNED NOT NULL,
  `tanggal_tes` date NOT NULL,
  `kategori_tes` enum('SKD','Tryout','Simulasi') NOT NULL DEFAULT 'SKD',
  `nilai_twk` decimal(6,2) NOT NULL DEFAULT 0.00,
  `nilai_tiu` decimal(6,2) NOT NULL DEFAULT 0.00,
  `nilai_tkp` decimal(6,2) NOT NULL DEFAULT 0.00,
  `total_skor` decimal(8,2) GENERATED ALWAYS AS (`nilai_twk` + `nilai_tiu` + `nilai_tkp`) STORED,
  `catatan` text DEFAULT NULL,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

