-- --------------------------------------------------------

--
-- Table structure for table `penilaian_binjas`
--

CREATE TABLE `penilaian_binjas` (
  `id` int(10) UNSIGNED NOT NULL,
  `siswa_id` int(10) UNSIGNED NOT NULL,
  `tanggal_tes` date NOT NULL,
  `institusi` enum('polri','tni') NOT NULL DEFAULT 'polri',
  `gender` enum('pria','wanita') NOT NULL DEFAULT 'pria',
  `lari_jarak_meter` decimal(7,2) NOT NULL DEFAULT 0.00,
  `pullup_repetisi` decimal(5,2) NOT NULL DEFAULT 0.00,
  `situp_repetisi` decimal(5,2) NOT NULL DEFAULT 0.00,
  `pushup_repetisi` decimal(5,2) NOT NULL DEFAULT 0.00,
  `shuttlerun_detik` decimal(6,2) NOT NULL DEFAULT 0.00,
  `lunges_repetisi` decimal(5,2) DEFAULT NULL,
  `renang_detik` decimal(6,2) DEFAULT NULL,
  `skor_akhir` decimal(6,2) DEFAULT NULL COMMENT 'Total skor hasil kalkulasi binjas',
  `predikat` varchar(30) DEFAULT NULL COMMENT 'Baik Sekali / Baik / Cukup / Kurang',
  `catatan` text DEFAULT NULL,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

