--
-- Table structure for table `penilaian_mapel`
--

CREATE TABLE `penilaian_mapel` (
  `id` int(10) UNSIGNED NOT NULL,
  `siswa_id` int(10) UNSIGNED NOT NULL,
  `tanggal_tes` date NOT NULL,
  `bahasa_indonesia` decimal(5,2) NOT NULL DEFAULT 0.00,
  `bahasa_inggris` decimal(5,2) NOT NULL DEFAULT 0.00,
  `matematika` decimal(5,2) NOT NULL DEFAULT 0.00,
  `pengetahuan_umum` decimal(5,2) NOT NULL DEFAULT 0.00,
  `wawasan_kebangsaan` decimal(5,2) NOT NULL DEFAULT 0.00,
  `rata_mapel` decimal(5,2) GENERATED ALWAYS AS (round((`bahasa_indonesia` + `bahasa_inggris` + `matematika` + `pengetahuan_umum` + `wawasan_kebangsaan`) / 5,2)) STORED,
  `catatan` text DEFAULT NULL,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

