--
-- Table structure for table `penilaian_psikologi`
--

CREATE TABLE `penilaian_psikologi` (
  `id` int(10) UNSIGNED NOT NULL,
  `siswa_id` int(10) UNSIGNED NOT NULL,
  `tanggal_tes` date NOT NULL,
  `kecerdasan` decimal(5,2) NOT NULL DEFAULT 0.00,
  `kecermatan` decimal(5,2) NOT NULL DEFAULT 0.00,
  `kepribadian` decimal(5,2) NOT NULL DEFAULT 0.00,
  `rata_psikologi` decimal(5,2) GENERATED ALWAYS AS (round((`kecerdasan` + `kecermatan` + `kepribadian`) / 3,2)) STORED,
  `status_psikologi` enum('Lulus','Tidak Lulus') GENERATED ALWAYS AS (case when `kecerdasan` >= 61 and `kecermatan` >= 61 and `kepribadian` >= 61 then 'Lulus' else 'Tidak Lulus' end) STORED,
  `catatan` text DEFAULT NULL,
  `sumber` enum('Manual','CAT') NOT NULL DEFAULT 'Manual',
  `sumber_referensi` varchar(100) DEFAULT NULL,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

