DROP TABLE IF EXISTS `v_profil_siswa`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u741010203_admin`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_profil_siswa`  AS SELECT `s`.`id` AS `id`, `s`.`nomor_induk` AS `nomor_induk`, `s`.`nama_lengkap` AS `nama_lengkap`, `u`.`email` AS `email`, `s`.`nomor_wa` AS `nomor_wa`, `s`.`jenis_kelamin` AS `jenis_kelamin`, `s`.`status_siswa` AS `status_siswa`, `s`.`tanggal_lahir` AS `tanggal_lahir`, timestampdiff(YEAR,`s`.`tanggal_lahir`,curdate()) AS `umur` FROM (`siswa` `s` left join `users` `u` on(`s`.`user_id` = `u`.`id`)) ;

